---@param activityId int
---@return CumulativeSalesActivityData | nil
function CumulativeSalesViewModel.GetCumulativeSalesActivityData(activityId)
    for id, tab in pairs(TaskVoidShopLocalData.tab) do
        if tab[2] == activityId then
            local taskGroupIdsSplit = string.split(tab[4], ",")
            ---@type CumulativeSalesActivityData
            local data = {
                activityId = tab[2],
                taskGroupIds = {},
                taskGroupNames = string.split(tab[7], ","),
                dayTaskGroupId = tab[6] or 0,
                dayTaskGroupName = tab[8],
                shopType = tonumber(tab[5]) or 0,
            }
            for _, taskGroupIdStr in ipairs(taskGroupIdsSplit) do
                table.insert(data.taskGroupIds, tonumber(taskGroupIdStr))
            end
            return data
        end
    end
    return nil
end

--- 用当前背包内道具数量更新 goods 字段
