--region 红点
--- 目前仅有一种注册红点，后续新增则要修改该方法
function CumulativeSalesViewModel.RefreshAllRedDots()
    ---@return boolean
    local CheckTaskRedDot = function(taskType, taskGroupId) 
        local taskList = CumulativeSalesViewModel.GetTaskList(taskType, taskGroupId)
        for _, task in ipairs(taskList) do
            if task.isReceive == 1 then
                return true
            end
        end
        return false
    end
    
    
    for _, tab in pairs(TaskVoidShopLocalData.tab) do
        local activityId = tab[2]
        local activityData = ActivityControl.GetActivityByID(activityId)
        local bRedDot = false
        -- 活动开启
        local bOpen = false
        if activityData then
            if activityData.timeType == 999 or  
                Global.isMiddleTime(activityData.beginTime, activityData.endTime) then
                bOpen = true
            end
        end
        if bOpen then
            --- 日常任务
            local taskGroupId = tab[6]
            if CheckTaskRedDot(CumulativeSalesViewModel.TaskTypeEnum.DAILY, taskGroupId) then
                bRedDot = true
            end

            --- 成就任务
            if not bRedDot then
                local taskGroupIdsSplit = string.split(tab[4], ",")
                for _, idStr in ipairs(taskGroupIdsSplit) do
                    local id = tonumber(idStr)
                    if CheckTaskRedDot(CumulativeSalesViewModel.TaskTypeEnum.ACHIEVEMENT, id) then
                        bRedDot = true
                        break
                    end
                end
            end

            -- 目前累销活动会同时存在两种，要特别处理
            if activityId == ActivityControl.activityTypeEnum.CUMULATIVE_SALES * 100 + 1 then
                ---@type RedDotData
                local dotData = RedDotControl.GetDotData("CumulativeSales2")
                dotData:SetState(bRedDot)
            else
                ---@type RedDotData
                local dotData = RedDotControl.GetDotData("CumulativeSales")
                dotData:SetState(bRedDot)
            end
        end
    end
end
--endregion 红点

