---@param taskGroupId int
---@param bSorted boolean
---@return AchievementTaskData[]
function CumulativeSalesViewModel.GetAchievementTaskList(taskGroupId, bSorted)
    if not cacheAchievementTaskDataMap[taskGroupId] then
        ---@type CumulativeSalesAchievementTaskData[]
        local list = {}
        for id, tab in pairs(ActiveLocalData.tab) do
            local activeId = tab[16]
            if activeId == taskGroupId then
                ---@type CumulativeSalesAchievementTaskData
                local data = {
                    taskId = id,
                    taskType = tab[2],
                }
                table.insert(list, data)
            end
        end
        cacheAchievementTaskDataMap[taskGroupId] = list
    end
    ---@type AchievementTaskData[]
    local taskList = {}
    --- 不知道为什么成就任务要分多个列表存储，因此这里得从多个列表获取
    for _, data in ipairs(cacheAchievementTaskDataMap[taskGroupId]) do
        ---@type AchievementTaskData
        local taskData = CumulativeSalesViewModel.GetAchievementTaskData(data.taskId, data.taskType)
        if taskData then
            table.insert(taskList, taskData)
        end
    end
    if bSorted then
        CumulativeSalesViewModel.SortTaskList(taskList)
    end
    return taskList
end

