---@param taskId int
---@return int, int @ currentProgress, maxProgress
function CumulativeSalesViewModel.GetDayTaskProgress(taskId)
    local taskData = TaskControl.EventRaidTaskDataList[taskId]
    if not taskData then
        return 0
    end
    local completeStr = string.split(taskData.complete, "_")
    local statisticId = tonumber(completeStr[1]) or 0
    local maxProgress = tonumber(completeStr[3]) or 1
    local progress = 0
    -- 每日登录这种好像不会有统计数据
    if taskData.isReceive == 1 or taskData.isComplete == 1 then
        progress = maxProgress
    else
        progress = TaskControl.EventRaidStatistics[statisticId] or 0
    end
    return progress, maxProgress
end

---@param taskGroupId int
---@param taskId int? @ default 0，0-全部领取
---@param callback fun()?
function CumulativeSalesViewModel.PerformDayTask(taskGroupId, taskId, callback)
    AchievementViewModel.TaskPerform(TaskControl.DayTaskType.EVENT_RAID, taskId or 0, nil, taskGroupId, function()
        Event.Go("ActivityDot")
        if callback then
            callback()
        end
    end)
end
