--- 获得商店要显示的货币列表
---@param shopType int
---@param outCoinList CumulativeSalesCoinData[]? @ 
---@return CumulativeSalesCoinData[]
function CumulativeSalesViewModel.GetShopCoinList(shopType, outCoinList)
    outCoinList = outCoinList or {}
    local shopData = ShoptypeLocalData.tab[shopType]
    if not shopData then
        return outCoinList
    end
    local coinSplit1 = string.split(shopData.icons, ";")
    for _, str1 in ipairs(coinSplit1) do
        local coinSplit2 = string.split(str1, ",")
        local coinStr = coinSplit2[1]
        local jumpStr = coinSplit2[2]
        local coins = string.split(coinStr, "_")
        local coinType = tonumber(coins[1])
        local coinId = tonumber(coins[2])
        local coinItem = ItemControl.GetItemByIdAndType(coinId, coinType)
        ---@type CumulativeSalesCoinData
        local costData = {
            goodsType = coinType,
            goodsID = coinId,
            goodsNum = coinItem.count,
            goodsIcon = coinItem.icon,
            jumpStr = jumpStr,
        }
        table.insert(outCoinList, costData)
    end
    return outCoinList
end

--- 获得商店的商品列表
---@param shopType int
---@field outShopItemList ShopItemData[]?
---@return ShopItemData[]
function CumulativeSalesViewModel.GetShopItemList(shopType, outShopItemList)
    outShopItemList = outShopItemList or {}
    local shopItems = ShopControl.GetCertainTypeShopData(shopType)
    if not shopItems then
        return outShopItemList
    end
    for _, shopItem in pairs(shopItems) do
        table.insert(outShopItemList, shopItem)
    end
    ---@param a ShopItemData
    ---@param b ShopItemData
    table.sort(outShopItemList, function(a, b)
        if a.sortIdx == b.sortIdx then
            return a.id < b.id
        end
        return a.sortIdx < b.sortIdx
    end)
    return outShopItemList
end

--- 检查商品是否锁定
---@param shopItem ShopItemData
---@param bPopTip boolean
---@return boolean
function CumulativeSalesViewModel.CheckShopItemLock(shopItem, bPopTip)
    local sysId = shopItem.buyLimit
    if sysId == 0 then
        return false
    end
    if SysLockControl.CheckSysLock(sysId) then
        return false
    end
    if bPopTip then
        Global.PopTip(SysLockControl.GetSystemLockTips(sysId), nil, true)
    end
    return true
end

--- 弹出购买界面，用户选择购买数量后购买
---@param shopItem ShopItemData
---@param callback fun(count:int)
function CumulativeSalesViewModel.BuyShopItem(shopItem, callback)
    local priceGoods = shopItem:GetPrice()
    local priceItem = ItemControl.GetItemByIdAndType(priceGoods.goodsID, priceGoods.goodsType)
    local bInfinite = shopItem.buyMaxCount == 0
    local restCount = bInfinite and 99 or shopItem.buyMaxCount - shopItem.buyCount
    local canBuyCount = math.floor(priceItem.count / priceGoods.goodsNum)
    MgrUI.Pop(UID.BuyPop_UI, {
        shopItem,
        function(count)
            -- 选择购买数量超过可买数量
            if count > canBuyCount then
                Global.PopTip(string.format(
                        MgrLanguageData.GetLanguageByKey("shop_ui_buyfail1"),
                        priceItem.name),
                        nil, true)
                return
            end
            -- 走购买接口
            ShopViewModel.SendBuyGoods({ shopItem.id, count}, function()
                if callback then
                    callback(count)
                end
            end)
        end,
        1,
        restCount,
        true,
        canBuyCount,
        nil,
    }, true)
end
