--- 获得角色随机台词id
---@param roleId int @ 0 则无行为
---@param readType int
---@return int @ 0 表示无
function CumulativeSalesViewModel.GetRandomActorLinesId(roleId, readType)
    if roleId == 0 then
        return 0
    end
    if not cacheActorLinesMap[roleId] then
        cacheActorLinesMap[roleId] = {}
    end
    if not cacheActorLinesMap[roleId][readType] then
        cacheActorLinesMap[roleId][readType] = CumulativeSalesViewModel.BuildActorLinesWeightMap(roleId, readType)
    end
    local _, linesId = CumulativeSalesViewModel.GetWeightRandomData(cacheActorLinesMap[roleId][readType])
    return linesId or 0
end

