--- 构建角色台词权重字典，不考虑解锁条件
---@param roleId int
---@param readType int
---@param outLinesMap CumulativeSalesWeightData[]?
---@return CumulativeSalesWeightData[] @ data = lineId
function CumulativeSalesViewModel.BuildActorLinesWeightMap(roleId, readType, outLinesMap)
    outLinesMap = outLinesMap or {}
    for _, tab in pairs(ActorLinesLocalData.tab) do
        if tab[2] == roleId and tab[5] == "0" and tab[3] == readType then
            ---@type CumulativeSalesWeightData
            local wData = {
                -- 当前没有权重值设置，固定为 10
                weight = 10,
                data = tab[1],
            }
            table.insert(outLinesMap, wData)
        end
    end
    return outLinesMap
end
