--region 时间
--- 将 Y-m-d-H-M-S 转换为 Y/m/d H:M
--- 若传入 endTimeStr 则为 [...] - [...]
---@param timeStr string
---@param endTimeStr string
---@return string
function CumulativeSalesViewModel.TimeStrConvert01(timeStr, endTimeStr)
    if Global.IsStrNil(timeStr) then
        return ""
    end
    local str1 = string.split(timeStr, "-")
    if Global.IsStrNil(endTimeStr) then
        return string.format("%s/%s/%s %s:%s", str1[1], str1[2], str1[3], str1[4], str1[5])
    end
    local str2 = string.split(endTimeStr, "-")
    return string.format("%s/%s/%s %s:%s - %s/%s/%s %s:%s",
        str1[1], str1[2], str1[3], str1[4], str1[5],
        str2[1], str2[2], str2[3], str2[4], str2[5])
end
--endregion 时间

--region 通用功能
--- 获取权重随机数据
---@param weightDataList CumulativeSalesWeightData[] @ 要求权重为独立值
---@return int, any @ index, data
function CumulativeSalesViewModel.GetWeightRandomData(weightDataList)
    if not weightDataList or #weightDataList == 0 then
        return 0, nil
    end
    
    local maxWeight = 0
    for _, wData in ipairs(weightDataList) do
        maxWeight = maxWeight + wData.weight
    end
    local randomNum = math.random(0, maxWeight)
    local curWeight = 0
    for i, wData in ipairs(weightDataList) do
        curWeight = curWeight + wData.weight
        if randomNum <= curWeight then
            return i, wData.data
        end
    end
    print("权重随机错误，返回第一个数据")
    return 1, weightDataList[1].data
end

--- 通用任务排序：可领取->未完成->已完成 (id升序)
---@param taskList AchievementTaskData[] | DayTaskData[]
function CumulativeSalesViewModel.SortTaskList(taskList)
    ---@param a AchievementTaskData | DayTaskData
    ---@param b AchievementTaskData | DayTaskData
    table.sort(taskList, function(a, b)
        if a.isReceive == b.isReceive then
            if a.isComplete == b.isComplete then
                return a.id < b.id
            else
                return a.isComplete < b.isComplete
            end
        else
            return a.isReceive > b.isReceive
        end
    end)
end

---@param taskId int
---@param taskType TaskControl.AchievementTaskType
---@return AchievementTaskData | nil
function CumulativeSalesViewModel.GetAchievementTaskData(taskId, taskType)
    ---@type AchievementTaskData
    local taskData
    if taskType == TaskControl.AchievementTaskType.NOVICE then
        taskData = TaskControl.NoviceDataList[taskId]
    elseif taskType == TaskControl.AchievementTaskType.GUIDE then
        taskData = TaskControl.GuideDataList[taskId]
    else
        taskData = TaskControl.AchievementDataList[taskId]
    end
    if not taskData then
        return nil
    end
    taskData.isComplete = TaskControl.CheckComplete(taskData.id) and 1 or 0
    taskData.isReceive = TaskControl.CheckAchieveReceived(taskData) and 1 or 0
    if taskData.isComplete == 1 or TaskControl.CheckTaskLock(taskData) then
        return taskData
    end
    return nil
end
